// Column: One column of an event table, in wire order.
type Column struct {
	name         string
	sql          SqlType
	kind         FieldKind
	values       Vocabulary
	values_ok    bool
	since        int64
	since_ok     bool
	retiredIn    int64
	retiredIn_ok bool
}

// Name: The SQL column name, also the struct field name.
func (self *Column) Name() string { return self.name }

// SQL: The lake type; its byte width is the wire width.
func (self *Column) SQL() SqlType { return self.sql }

// Kind: How the column is streamed.
func (self *Column) Kind() FieldKind { return self.kind }

// Values: The telemetry enum an `enum8` column holds.
func (self *Column) Values() (Vocabulary, bool) { return self.values, self.values_ok }

// Since: The version that added the column; none: present from the table's first known version.
func (self *Column) Since() (int64, bool) { return self.since, self.since_ok }

// RetiredIn: The version that retired it. A retired column stays in the DDL (after the live ones),
// is appended as NULL, and leaves the wire.
func (self *Column) RetiredIn() (int64, bool) { return self.retiredIn, self.retiredIn_ok }

// ProvenanceColumn: A provenance column the ingester prepends to every table: who sent the row, in which
// batch, at which version. Never on the wire as a field.
type ProvenanceColumn struct {
	name string
	sql  SqlType
}

// Name: Its SQL name.
func (self *ProvenanceColumn) Name() string { return self.name }

// SQL: Its SQL type, never NULL.
func (self *ProvenanceColumn) SQL() SqlType { return self.sql }

// Rows: The rows of a table one ledger role covers.
type Rows struct {
	kind  RowsKind
	value any
}

func (self *Rows) Kind() RowsKind { return self.kind }

func (self *Rows) AsSome() (*RowsSome, bool) {
	c, ok := self.value.(*RowsSome)
	return c, ok
}

// RowsSome: The rows whose `of` column holds one of `kinds`; the table has exactly one such column.
type RowsSome struct {
	of    Vocabulary
	kinds rt.List[*Member]
}

// Of: The vocabulary whose column splits the rows.
func (self *RowsSome) Of() Vocabulary { return self.of }

// Kinds: The members covered.
func (self *RowsSome) Kinds() rt.List[*Member] { return self.kinds }

// Role: One ledger leg a table's rows contribute, or the statement that they move nothing.
type Role struct {
	rows            *Rows
	currency        Currency
	bucket          Bucket
	sign            int64
	token           string
	leg             Leg
	leg_ok          bool
	filter          string
	filter_ok       bool
	amount_id       string
	amount_ok       bool
	item_id         string
	item_ok         bool
	player_id       string
	player_ok       bool
	counterparty_id string
	counterparty_ok bool
	counted         bool
	dedupOf         string
	dedupOf_ok      bool
	untilVersion    int64
	untilVersion_ok bool
	note            string
}

// Rows: The rows it covers.
func (self *Role) Rows() *Rows { return self.rows }

// Currency: What moves.
func (self *Role) Currency() Currency { return self.currency }

// Bucket: Mint, sink or transfer.
func (self *Role) Bucket() Bucket { return self.bucket }

// Sign: +1 credit, -1 debit, 0: the amount is already signed (or there is none).
func (self *Role) Sign() int64 { return self.sign }

// Token: The stable vocabulary the economy panel groups on.
func (self *Role) Token() string { return self.token }

// Leg: The side a single-row transfer reads; none for a table with one row per side.
func (self *Role) Leg() (Leg, bool) { return self.leg, self.leg_ok }

// Filter: An extra predicate on the table's own columns (DuckDB SQL).
func (self *Role) Filter() (string, bool) { return self.filter, self.filter_ok }

// AmountID: The magnitude; none for a row that documents a path with no amount.
func (self *Role) AmountID() (string, bool) { return self.amount_id, self.amount_ok }

// ItemID: For item legs: the column naming the item.
func (self *Role) ItemID() (string, bool) { return self.item_id, self.item_ok }

// PlayerID: Whose ledger the leg lands on; none: the header's player_id.
func (self *Role) PlayerID() (string, bool) { return self.player_id, self.player_ok }

// CounterpartyID: The other side, if any.
func (self *Role) CounterpartyID() (string, bool) { return self.counterparty_id, self.counterparty_ok }

// Counted: Summed into the reconciliation (true), or real telemetry that must not be summed.
func (self *Role) Counted() bool { return self.counted }

// DedupOf: The token this row would double-count with.
func (self *Role) DedupOf() (string, bool) { return self.dedupOf, self.dedupOf_ok }

// UntilVersion: The last version whose rows this role reads; none: every version.
func (self *Role) UntilVersion() (int64, bool) { return self.untilVersion, self.untilVersion_ok }

// Note: Why, citing a function, never a line number.
func (self *Role) Note() string { return self.note }

// Event: One telemetry table: the rows of one event type.
type Event struct {
	description    string
	version        uint8
	since          int64
	tier           Tier
	producers      rt.List[Producer]
	enqueue        Enqueue
	columns        rt.KeyedList[string, Column]
	ledger         rt.List[*Role]
	ledgerKinds_id string
	ledgerKinds_ok bool
}

// Description: What one row records.
func (self *Event) Description() string { return self.description }

// Version: The current layout version: the wire version byte and the lake's event_version.
func (self *Event) Version() uint8 { return self.version }

// Since: The first version whose layout this catalogue knows. Tables older than the schema lock
// start at 2, its floor; their earlier history is lost.
func (self *Event) Since() int64 { return self.since }

// Tier: Ring policy.
func (self *Event) Tier() Tier { return self.tier }

// Producers: The processes that own a ring for it (none: read-only history).
func (self *Event) Producers() rt.List[Producer] { return self.producers }

// Enqueue: How the client enqueues it.
func (self *Event) Enqueue() Enqueue { return self.enqueue }

// Columns: The body columns after the header, in wire order, retired ones where they stood.
func (self *Event) Columns() rt.KeyedList[string, Column] { return self.columns }

// Ledger: What its rows mean to the ledgers; empty: no ledger at all.
func (self *Event) Ledger() rt.List[*Role] { return self.ledger }

// LedgerKindsID: The enum8 column the ledger is typed by. When set, every live member of its vocabulary
// is covered by some role (L-0111), so a new kind cannot ship without a ledger decision.
func (self *Event) LedgerKindsID() (string, bool) { return self.ledgerKinds_id, self.ledgerKinds_ok }

// Member: A member of vocabulary `v`: what a ledger role splitting on a `v` column names.
