// HeaderColumns: The two header columns every table starts with; `since` is the table's first version.
type HeaderColumns struct {
	rows rt.KeyedList[string, Column]
}

// Len returns the number of entries.
func (self *HeaderColumns) Len() int { return self.rows.Len() }

// At returns entry i, in source order.
func (self *HeaderColumns) At(i int) *Column { return self.rows.At(i) }

// All yields every entry in source order.
func (self *HeaderColumns) All() iter.Seq[*Column] { return self.rows.All() }

// Find returns the entry whose name is key.
func (self *HeaderColumns) Find(key string) (*Column, bool) { return self.rows.Find(key) }

// ProvenanceColumns: The provenance prefix of every CREATE TABLE, in order.
type ProvenanceColumns struct {
	rows rt.KeyedList[string, ProvenanceColumn]
}

// Len returns the number of entries.
func (self *ProvenanceColumns) Len() int { return self.rows.Len() }

// At returns entry i, in source order.
func (self *ProvenanceColumns) At(i int) *ProvenanceColumn { return self.rows.At(i) }

// All yields every entry in source order.
func (self *ProvenanceColumns) All() iter.Seq[*ProvenanceColumn] { return self.rows.All() }

// Find returns the entry whose name is key.
func (self *ProvenanceColumns) Find(key string) (*ProvenanceColumn, bool) { return self.rows.Find(key) }

type telemetryData struct {
	events            rt.Map[EventType, *Event]
	headerColumns     HeaderColumns
	provenanceColumns ProvenanceColumns
}

